corrected_code:
import { verifyToken } from "./auth.ts";

const kv = await Deno.openKv();

Deno.serve(async (req: Request) => {
  const url = new URL(req.url);
  const match = url.pathname.match(/^\/api\/organizations\/([^\/]+)\/keys\/([^\/]+)$/);

  if (req.method === "GET" && match) {
    const [_, orgId, keyId] = match;
    const user = await verifyToken(req.headers.get("Authorization"));
    if (!user) return new Response("Unauthorized", { status: 401 });

    // Verify user membership and required permissions for the organization in Deno KV
    const memberEntry = await kv.get(["org_members", orgId, user.id]);
    if (!memberEntry.value || (memberEntry.value as any).role !== "admin") {
      return new Response(JSON.stringify({ error: "Forbidden: Not an organization admin" }), { status: 403 });
    }

    const keyEntry = await kv.get(["organizations", orgId, "api_keys", keyId]);
    if (!keyEntry.value) {
      return new Response(JSON.stringify({ error: "Key not found" }), { status: 404 });
    }

    return new Response(JSON.stringify(keyEntry.value), {
      headers: { "Content-Type": "application/json" }
    });
  }

  return new Response("Not Found", { status: 404 });
});
